import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा","description":"","frontmatter":{},"headers":[],"relativePath":"hi/84-考古协议总纲.md","filePath":"hi/84-考古协议总纲.md","lastUpdated":1789183869000}'),i={name:"hi/84-考古协议总纲.md"};function h(l,t,o,n,p,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="पुरातत्व-प्रोटोकॉल-सामान्य-रूपरेखा" tabindex="-1">पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा <a class="header-anchor" href="#पुरातत्व-प्रोटोकॉल-सामान्य-रूपरेखा" aria-label="Permalink to &quot;पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>84</td></tr><tr><td>मॉड्यूल</td><td>अंतर-पटल अंतःक्रिया और समय-नियम</td></tr><tr><td>कीवर्ड</td><td>पुरातत्व-प्रोटोकॉल, प्रतिकृति-दर्पण, पृथक-स्थान, केवल-ज्ञान-वापसी, निम्न-प्रदूषण</td></tr></tbody></table><h2 id="i-पुरातत्व-प्रोटोकॉल-की-स्थिति-और-लक्ष्य" tabindex="-1">I. पुरातत्व-प्रोटोकॉल की स्थिति और लक्ष्य <a class="header-anchor" href="#i-पुरातत्व-प्रोटोकॉल-की-स्थिति-और-लक्ष्य" aria-label="Permalink to &quot;I. पुरातत्व-प्रोटोकॉल की स्थिति और लक्ष्य&quot;">​</a></h2><p>अंतर-पटल पुरातत्व और समय-प्रत्यावर्तन पुरातत्व लंगर सहजीवी सभ्यता के लिए ऐतिहासिक-ज्ञान प्राप्ति और ब्रह्मांड-विकास की समझ के महत्वपूर्ण साधन हैं। तथापि, पुरातत्व-व्यवहार स्वयं अत्यधिक जोखिमपूर्ण है — लक्ष्य पटल या लक्ष्य-काल में सीधे प्रवेश कर उत्खनन करने से लक्ष्य-वस्तु को भौतिक-क्षति, नियम-क्षोभ और सांस्कृतिक-प्रदूषण हो सकता है। पुरातत्व-व्यवहार को विनियमित करने और पुरातत्व-जोखिम घटाने हेतु हेंग-ब्रह्मांड ने एकीकृत «पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा» बनाई है, जो सभी अंतर-पटल और समय-प्रत्यावर्तन पुरातत्व-गतिविधियों का मूल संचालन-विधान है।</p><p>पुरातत्व-प्रोटोकॉल के केंद्रीय लक्ष्य «तीन अधिकतम» में संक्षेपित किए जा सकते हैं: पूर्ण ऐतिहासिक-ज्ञान का अधिकतम अर्जन, लक्ष्य-वस्तु पर हस्तक्षेप और क्षति का अधिकतम घटाव, और पुरातत्व-कर्मियों की सुरक्षा का अधिकतम आश्वासन। इन तीन लक्ष्यों के बीच आंतरिक तनाव है — ज्ञान-अर्जन की पूर्णता प्रायः गहन संपर्क माँगती है, जबकि निम्न-हस्तक्षेप सिद्धांत संपर्क की गहराई सीमित करता है। पुरातत्व-प्रोटोकॉल की सारी संस्थागत रचना इन तीनों के बीच इष्टतम संतुलन खोजने हेतु है।</p><p>पुरातत्व-प्रोटोकॉल निम्न परिदृश्यों पर लागू: अज्ञात पटलों की सभ्यता-अवशेषों का पुरातात्विक-सर्वेक्षण, समय-प्रत्यावर्तन द्वारा विलुप्त सभ्यताओं का ऐतिहासिक-पुनर्स्थापन, अपने पटल के प्राचीन-अवशेषों का नियम-स्तरीय गहन पुरातत्व, और नियम-खंडित पटलों में प्राचीन-अवशेषों का बचाव-उत्खनन।</p><h2 id="ii-पुरातत्व-योजना-के-तीन-तत्व" tabindex="-1">II. पुरातत्व-योजना के तीन तत्व <a class="header-anchor" href="#ii-पुरातत्व-योजना-के-तीन-तत्व" aria-label="Permalink to &quot;II. पुरातत्व-योजना के तीन तत्व&quot;">​</a></h2><p>हेंग-ब्रह्मांड की मानक पुरातत्व-योजना तीन केंद्रीय तत्वों से बनी है, जिन्हें «पुरातत्व के तीन तत्व» कहा जाता है:</p><h3 id="_2-1-प्रतिकृति-दर्पण" tabindex="-1">2.1 प्रतिकृति-दर्पण <a class="header-anchor" href="#_2-1-प्रतिकृति-दर्पण" aria-label="Permalink to &quot;2.1 प्रतिकृति-दर्पण&quot;">​</a></h3><p>प्रतिकृति-दर्पण स्थान-न्यायिक सिद्धांत नियमों पर आधारित उच्च-परिशुद्धता प्रतिकृति-उपकरण है, जो मूल-वस्तु को स्पर्श किए बिना लक्ष्य-क्षेत्र की भौतिक, ऊर्जा और सूचना-संरचनाओं का 1:1 पूर्ण प्रतिकृति कर सकता है। प्रतिकृति-दर्पण का कार्य-सिद्धांत है स्थान-नियम स्कैनिंग द्वारा लक्ष्य-क्षेत्र की सभी कण-अवस्थाओं और ऊर्जा-क्षेत्र वितरणों का स्कैन करना, फिर पृथक-स्थान में पूर्णतः समान प्रति का पुनर्निर्माण। प्रतिकृति-प्रक्रिया मूल-वस्तु की कोई अवस्था नहीं बदलती, अतः पुरातत्व-स्थल पर कोई भौतिक हस्तक्षेप नहीं होता।</p><p>प्रतिकृति-दर्पण की प्रतिकृति-परिशुद्धता उप-परमाणु स्तर तक पहुँचती है, लक्ष्य-क्षेत्र की भौतिक-संरचनाएँ, ऊर्जा-अवशेष, चेतना-छाप और यहाँ तक कि कारण-शृंखला खंड पूर्ण रूप से पुनर्स्थापित कर सकती है। प्रतिकृति-सीमा पुरातत्व-आवश्यकता अनुसार समायोज्य; न्यूनतम प्रतिकृति-इकाई एक अकेला कलाकृति, और अधिकतम सम्पूर्ण अवशेष-समूह को आच्छादित कर सकती है। प्रतिकृति-समय सीमा के आकार पर निर्भर; एकल कलाकृति की प्रतिकृति सामान्यतः मिनटों में, बड़े अवशेष-समूह की कई दिनों में।</p><h3 id="_2-2-पृथक-स्थान" tabindex="-1">2.2 पृथक-स्थान <a class="header-anchor" href="#_2-2-पृथक-स्थान" aria-label="Permalink to &quot;2.2 पृथक-स्थान&quot;">​</a></h3><p>पृथक-स्थान स्थान-न्यायिक सिद्धांत-प्रेषण प्रौद्योगिकी द्वारा निर्मित स्वतंत्र नियम-क्षेत्र है, जो प्रतिकृति-दर्पण द्वारा उत्पन्न पुरातत्व-प्रतियों को धारण करने और पुरातत्व-कर्मियों के कार्य-स्थल के रूप में सेवा करता है। पृथक-स्थान लक्ष्य पटल या लक्ष्य-काल से पूर्ण नियम-अवरोध द्वारा पृथक है, यह सुनिश्चित करते हुए कि पुरातत्व-संचालन मूल-लक्ष्य पर कोई विपरीत-प्रभाव न डाले।</p><p>पृथक-स्थान के आंतरिक नियम-प्राचल पुरातत्व-आवश्यकता अनुसार अनुकूलित किए जा सकते हैं, जिनमें: कलाकृति-प्रतियों की स्थिरता सुनिश्चित हेतु लक्ष्य पटल के पर्यावरण-प्राचलों का अनुकरण, पुरातत्व-अनुसंधान में सहायता हेतु विशेष विश्लेषणात्मक नियम-क्षेत्रों की स्थापना, और कर्मियों की ऊर्जा-चेतना के बहिर्गमन रोकने हेतु कड़े प्रदूषण-रोकथाम नियंत्रण क्षेत्रों की स्थापना। पृथक-स्थान का आकार आवश्यकता अनुसार विस्तार-योग्य; अधिकतम सम्पूर्ण नगर-स्तरीय अवशेष-प्रति को समाहित कर सकता है।</p><h3 id="_2-3-केवल-ज्ञान-वापसी" tabindex="-1">2.3 केवल-ज्ञान-वापसी <a class="header-anchor" href="#_2-3-केवल-ज्ञान-वापसी" aria-label="Permalink to &quot;2.3 केवल-ज्ञान-वापसी&quot;">​</a></h3><p>«केवल-ज्ञान-वापसी» पुरातत्व-प्रोटोकॉल के केंद्रीय सिद्धांतों में से एक है, जिसका अर्थ है कि पुरातत्व-प्रक्रिया में लक्ष्य-वस्तु से केवल अमूर्त ज्ञान और सूचना प्राप्त हो; कोई भौतिक-पदार्थ, ऊर्जा या जीवन-रूप वापस नहीं लाया जाए। पृथक-स्थान में प्रति का अध्ययन करने के बाद पुरातत्व-कर्मी केवल अनुसंधान-निष्कर्ष, आँकड़ा-अभिलेख और विश्लेषण-रिपोर्ट शुद्ध सूचना के रूप में अपने पटल में ला सकते हैं; प्रति स्वयं और उससे निकाले गए कोई भौतिक-नमूने पृथक-स्थान में ही नष्ट किए जाने चाहिए।</p><p>इस सिद्धांत का मूल उद्देश्य अंतर-पटल प्रदूषण और समय-रेखा क्षोभ को रोकना है। प्रति से निकाली गई एक कण-धूल भी लक्ष्य पटल की नियम-सूचना वहन कर सकती है; अपने पटल के नियम-नेटवर्क में प्रवेश करते ही अप्रत्याशित शृंखला-प्रतिक्रियाएँ उत्पन्न कर सकती है। अतः «केवल-ज्ञान-वापसी» कोई विचार-विमर्श-योग्य संचालन-सुझाव नहीं, बल्कि कानूनी-बलपूर्ण कठोर सिद्धांत है।</p><h2 id="iii-पुरातत्व-संचालन-की-मानक-प्रक्रिया" tabindex="-1">III. पुरातत्व-संचालन की मानक प्रक्रिया <a class="header-anchor" href="#iii-पुरातत्व-संचालन-की-मानक-प्रक्रिया" aria-label="Permalink to &quot;III. पुरातत्व-संचालन की मानक प्रक्रिया&quot;">​</a></h2><p>एक पूर्ण अंतर-पटल या समय-प्रत्यावर्तन पुरातत्व-संचालन निम्न मानक प्रक्रिया का पालन करता है:</p><table tabindex="0"><thead><tr><th>चरण</th><th>संचालन-सामग्री</th><th>उत्तरदायी पक्ष</th><th>अवधि-संदर्भ</th></tr></thead><tbody><tr><td>प्रथम चरण: परियोजना-अनुमोदन</td><td>पुरातत्व-आवेदन प्रस्तुत, लक्ष्य, सीमा और योजना स्पष्ट, स्तर A संचरण-अनुमति या प्रत्यावर्तन-अनुमति प्राप्त</td><td>पुरातत्व-दल → पटल प्रशासन / समय-नियम समिति</td><td>7-30 दिन</td></tr><tr><td>द्वितीय चरण: पूर्व-अवलोकन</td><td>«पहले अवलोकन, फिर सीमित हस्तक्षेप» मानदंड अनुसार लक्ष्य-क्षेत्र का कम से कम 72 घंटे शुद्ध अवलोकन</td><td>पुरातत्व-दल</td><td>72+ घंटे</td></tr><tr><td>तृतीय चरण: प्रतिकृति-दर्पण तैनाती</td><td>लक्ष्य-क्षेत्र के निकट सुरक्षित स्थान पर प्रतिकृति-दर्पण तैनात, प्रतिकृति-सीमा और परिशुद्धता-प्राचल निर्धारित</td><td>तकनीकी दल</td><td>घंटों से दिनों तक</td></tr><tr><td>चतुर्थ चरण: प्रति-निर्माण</td><td>प्रतिकृति-दर्पण सक्रिय कर लक्ष्य-क्षेत्र को पूर्व-निर्मित पृथक-स्थान में पूर्ण प्रतिकृति</td><td>तकनीकी दल</td><td>मिनटों से दिनों तक</td></tr><tr><td>पंचम चरण: पृथक-स्थान पुरातत्व</td><td>पुरातत्व-कर्मी पृथक-स्थान में प्रवेश कर प्रति पर व्यवस्थित उत्खनन, विश्लेषण और अनुसंधान</td><td>पुरातत्व-दल</td><td>दिनों से वर्षों तक</td></tr><tr><td>षष्ठ चरण: ज्ञान-संगठन</td><td>पुरातत्व-उपलब्धियाँ संगठित, अनुसंधान-रिपोर्ट और ज्ञान-कोष निर्मित, सभी उपलब्धियाँ शुद्ध सूचना-रूप में सुनिश्चित</td><td>पुरातत्व-दल</td><td>दिनों से महीनों तक</td></tr><tr><td>सप्तम चरण: प्रस्थान और विनाश</td><td>पुरातत्व-कर्मी पृथक-स्थान से बाहर, सभी प्रति-पदार्थ और ऊर्जा-अवशेष नष्ट, पृथक-स्थान बंद</td><td>तकनीकी दल + पर्यवेक्षण दल</td><td>घंटे</td></tr><tr><td>अष्टम चरण: पश्चात-लेखापरीक्षा</td><td>पूर्ण पुरातत्व-रिपोर्ट प्रस्तुत, समय-नियम लेखापरीक्षा समिति या पटल प्रशासन की पश्चात-लेखापरीक्षा स्वीकार</td><td>लेखापरीक्षा समिति</td><td>30 दिनों में</td></tr></tbody></table><h2 id="iv-पुरातत्व-कर्मियों-की-योग्यता-और-नैतिक-आवश्यकताएँ" tabindex="-1">IV. पुरातत्व-कर्मियों की योग्यता और नैतिक आवश्यकताएँ <a class="header-anchor" href="#iv-पुरातत्व-कर्मियों-की-योग्यता-और-नैतिक-आवश्यकताएँ" aria-label="Permalink to &quot;IV. पुरातत्व-कर्मियों की योग्यता और नैतिक आवश्यकताएँ&quot;">​</a></h2><p>अंतर-पटल और समय-प्रत्यावर्तन पुरातत्व में संलग्न कर्मियों के पास निम्न योग्यताएँ होनी चाहिए: स्थान-न्यायिक सिद्धांत-प्रेषण प्रणाली के तृतीय स्तर से ऊपर की साधना, पुरातत्व-नैतिकता समिति की योग्यता-प्रमाणन, कम से कम 100 घंटे का अनुकरणीय पुरातत्व-प्रशिक्षण, और सहजीवी कानूनों के उल्लंघन का कोई अभिलेख नहीं।</p><p>पुरातत्व-कर्मियों को निम्न नैतिक आवश्यकताओं का पालन करना चाहिए: लक्ष्य सभ्यता की संस्कृति और आस्थाओं का सम्मान, अनुसंधान में सांस्कृतिक-भेदभाव या मूल्य-निर्णय से बचाव; पुरातत्व-स्थल की अखंडता की रक्षा, कलाकृतियाँ प्राप्त करने हेतु अवशेष-संरचनाएँ नष्ट न करना; पुरातत्व-खोजों का सत्य अभिलेखन और रिपोर्टन, आँकड़ों में छेड़छाड़ या छुपाव नहीं; और «केवल-ज्ञान-वापसी» सिद्धांत का पालन, कोई भौतिक-नमूना निजी रूप से पृथक-स्थान से बाहर नहीं ले जाना।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा हेंग-ब्रह्मांड द्वारा ज्ञान-अन्वेषण और सभ्यता-संरक्षण के बीच स्थापित संस्थागत सेतु है। यह प्रतिकृति-दर्पण, पृथक-स्थान और केवल-ज्ञान-वापसी तीन तत्वों को तकनीकी आधार, मानकीकृत प्रक्रिया को संचालन-रूपरेखा, और कर्मियों की योग्यता-नैतिक आवश्यकताओं को मानवीय-गारंटी बनाकर «निम्न-प्रदूषण, उच्च-दक्षता, अनुरेखणीयता» की पुरातत्व-प्रतिमान रचता है। यह प्रतिमान सुनिश्चित करता है कि हेंग-ब्रह्मांड ऐतिहासिक-सत्य की खोज में अन्य सभ्यताओं और युगों के प्रति सदैव उच्चतम सम्मान बनाए रखे।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>85-复制镜异地考古方案 (प्रतिकृति-दर्पण बाह्य-स्थल पुरातत्व-योजना)</li><li>86-隔离空间低污染流程 (पृथक-स्थान निम्न-प्रदूषण प्रक्रिया)</li><li>87-仅回传知识原则 (केवल-ज्ञान-वापसी सिद्धांत)</li></ul>',27)])])}const b=a(i,[["render",h]]);export{c as __pageData,b as default};
